#include "AI/AskirPerceptionComponent.h"
#include "Engine/World.h"
UAskirPerceptionComponent::UAskirPerceptionComponent(){PrimaryComponentTick.bCanEverTick=true;}
void UAskirPerceptionComponent::Remember(AActor*A,float T,float C){if(!IsValid(A)||!GetWorld()||!FMath::IsFinite(T)||!FMath::IsFinite(C))return;for(auto&M:Memories)if(M.Actor==A){M.LastKnownLocation=A->GetActorLocation();M.Threat=FMath::Max(0.f,T);M.Confidence=FMath::Clamp(C,0.f,1.f);M.LastSeenTime=GetWorld()->GetTimeSeconds();return;}FAskirMemory M;M.Actor=A;M.LastKnownLocation=A->GetActorLocation();M.Threat=FMath::Max(0.f,T);M.Confidence=FMath::Clamp(C,0.f,1.f);M.LastSeenTime=GetWorld()->GetTimeSeconds();Memories.Add(M);}
void UAskirPerceptionComponent::TickComponent(float D,ELevelTick T,FActorComponentTickFunction*F){Super::TickComponent(D,T,F);if(!GetWorld())return;double N=GetWorld()->GetTimeSeconds();for(int32 I=Memories.Num()-1;I>=0;--I)if(!IsValid(Memories[I].Actor.Get())||N-Memories[I].LastSeenTime>FMath::Max(0.f,ForgetAfterSeconds))Memories.RemoveAt(I);}
